        description: "\"تورید وتركییب وتشغیل واختبار بابلر مصنوعاً من البلاستیك والمطاط\nوأن یكون من النوع الثابت التدفق عند ( UL Stable) العالي الجودة\nضغط تشغیل بین ١٫٤ إلى ٦٫٢ بار ( ٢٠ إلى ٩٠ باوند/ بوصة ٢) وأن\nیحتوي على فلتر منفصل یثبت بأسفله عند التركیب. یجب أن یوفر البابلر\nخیارات دفق ثابتة ٢و ١و ٠٫٥ و ٠٫٢٥ جالون/دقیقة ویتم تركیبة على جسم\nالرشاش ذاتي الارتداد . وجمیع ما یلزم لاتمام العمل\nعلى الوجة الامثل طبقا للمواصفات الفنیة .",
