        description: "توريد وتركيب ليات التنقيط الثابتة التدفق مصنعة من البولي اثيلين المنخفض الكثافة. والذي يحتوي على نسبة 2.8 % من الكربون الأسود وأن يتحمل ضغط تشغيل حتى 4.1 بار وكذلك تتحمل درجة حرارة المياه حتى 43.3 م ودرجة حرارة البيئة المحيطة حتى 51.7 م. يجب أن تكون الليات مصنعة من طبقتين الداخلية سوداء والخارجية بنية اللون لتتوافق مع\nلون التربة الزراعية وتحقق أعلى مقاومة للكيماويات والأشعة فوق البنفسجية ونمو الطحالب. يجب أن يكون القطر الخارجي لهذه الليات 16.1 مم والداخلي 13.6 مم وسمك الجدار 1.2 مم وتقبل التوصيل باستخدام كلا من الوصلات الانضغاطية وكذلك المحززة مقاس 17 مم.\nيجب أن تحتوي هذه الخطوط على نقاطات داخلية مقاومة للانسداد من النوع الثابت التدفق عند ضغط تشغيل يتراوح من 0.6 الى 4.1 بار) 8.5 إلى 60 باوند/ بوصة 2 .)\nيجب أن توفر 3.5 لتر/ساعة على مسافة 18 انش . وأن يتم تركيب هذه\nالليات على سطح الأرض وتثبيتها بأوتاد بلاستيكية على مسافات بينية حسب خرائط التصميم.\nيجب أن لا تظهر أية شقوق أو مظاهر تلف على هذه العينات بعد الفحص",
