                          "description":  "صيانة الرصف الأسفلتي من خلال تنفيذ طبقة تغطية رقيقة (Overlay) بفرد طبقة سطحية من الأسفلت الساخن بسماكة نهائية مضغوطة قدرها (3 سم) من خلطة أسفلتية بطريقة مارشال صنف (......) تدرج (......)، يشمل العمل تنظيف وتجهيز السطح القائم وإزالة الأتربة والشوائب والمواد المفككة ثم رش مادة رابطة من الإسفلت السائل RC-2 بمعدل (0.20 لتر/م2)، وفرش الخلطة الأسفلتية بالسماكة المطلوبة باستخدام المعدات المناسبة، ثم دمكها حتى تحقيق الكثافة المطلوبة كما يشمل البند تسوية السطح النهائي بحيث لا تظهر أي تموجات أو فروقات منسوب مع الرصف المجاور، ومعالجة الوصلات الطولية والعرضية بصورة سليمة، وتنظيف الموقع وإزالة جميع المخلفات والنواتج الناتجة عن الأعمال، وإجراء كافة الاختبارات اللازمة لاعتماد الأعمال، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
