                          "name":  "صيانة بطبقة الملاط الأسفلتي Slurry Seal",
                          "description":  "صيانة بطبقة الملاط الأسفلتي Slurry Seal:\nمعالجة وقائية سطحية بفرد طبقة ملاط أسفلتي مكونة من خليط متجانس من ركام ناعم جيد التدرج ومستحلب أسفلتي معدل وماء وإضافات، بسماكة لا تتجاوز (10 ملم)، يشمل البند تنظيف وتجهيز السطح القائم وتعبئة الشقوق وتصميم الخلطة واعتمادها، وفردها بالمعدة المتخصصة (Slurry Paver) بانتظام دون تموجات، ومعالجة الوصلات، ومنع المرور حتى تمام التصلب والفتح للحركة وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
