                          "description":  "استبدال وتركيب سياج شبك للجزيرة الوسطية (Median Chain-Link Fence)\nاستبدال وتركيب سياج شبك معدني مجلفن بالغمس الساخن للجزيرة الوسطية للطريق، بالأبعاد والارتفاعات المعتمدة، مكون من أعمدة فولاذية مجلفنة وشبك سلكي مجلفن مشدود ومثبت وفق الأصول الفنية، شاملا جميع ملحقات التثبيت والشد والربط والدعامات والبراغي والمشابك المجلفنة، وكافة الأعمال المدنية اللازمة من الحفر والردم وصب القواعد الخرسانية والتسليح والتثبيت وضبط المناسيب والاستقامة، ومعالجة جميع الوصلات ضد التآكل، وإزالة وترحيل العناصر التالفة إن وجدت، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
