                          "name":  "علامات الطرق الخزفية (Ceramic Stud)",
                          "description":  "علامات الطرق الخزفية (Ceramic Stud)\nاستبدال وتركيب علامات الطرق الخزفية (Ceramic Stud)باللون المطلوب عالية المقاومة للتآكل والصدمات والعوامل الجوية، بقطر (10 سم) وبارتفاع محدب يتراوح بين (90 ملم - 150 ملم) شاملا إزالة العلامات التالفة إن وجدت، وتجهيز وتنظيف سطح الرصف، والتثبيت باستخدام مادة لاصقة إيبوكسية أو مواد تثبيت معتمدة، وجميع المواد والمعدات والعمالة اللازمة لإتمام العمل، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
