                          "description":  "مصدات خرسانية لمواقف السيارات (Wheel Stops)\nاستبدال وتركيب مصدات خرسانية مسبقة الصب مانعة لعجلات السيارات (Wheel Stops) بمقاس (15 × 20 × 180 سم)، مصنوعة من خرسانة لا تقل مقاومة ضغطها عن (25 ميجا باسكال) عند عمر 28 يوما، ومزودة بفتحات ومرابط تثبيت مجلفنة أو قضبان تثبيت فولاذية حسب التصميم المعتمد، شاملة أعمال التوريد والنقل والتركيب وضبط المحاذاة والتثبيت الميكانيكي على الرصف أو الخرسانة القائمة، وإزالة وترحيل المصدات التالفة إن وجدت، وجميع المواد والمعدات اللازمة لإنجاز العمل، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
