                          "description":  "أعمدة مرنة بوجه عاكس أسطواني (High Performance Tuff Delineator)\nاستبدال وتركيب أعمدة مرنة بوجه عاكس أسطواني (High Performance Tuff Delineator) دائرية الشكل بارتفاع (107 سم) وقطر (6 سم)، مصنوعة من البلاستيك عالي المرونة والقوة والمقاوم للصدمات والعوامل الجوية والأشعة فوق البنفسجية، ومزودة بوجه أو شرائط عاكسة عالية الوضوح، مع كيبل داخلي عالي الشد وقاعدة بلاستيكية صلدة، قابلة للانحناء والعودة إلى وضعها الأصلي بعد الاصطدام، شاملة إزالة الأعمدة التالفة إن وجدت، وتجهيز السطح، وتوريد وتركيب جميع المرابط والمثبتات ومواد التثبيت المعتمدة، وضبط مواقع التركيب وفق المخططات المعتمدة، وإجراء الاختبارات اللازمة والتأكد من ثباتها وجاهزيتها للاستخدام، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
