                          "description":  "أعمال ازالة كافة المخلفات والنباتات والأعشاب شامل تنظيف حرم الطريق ومنشآته المختلفة والتخلص من كافة المواد الناتجة عن الإزالة والمواد غير المرغوب بها من حدود أعمال الطريق ونقلها إلى المواقع المعتمدة كما يشمل جميع الآليات والمعدات والعمالة وتنفيذ كافة التحويلات والممرات المؤقتة وإجراءات السلامة والأمان وأعمال التدعيم وكل ما يلزم لتنفيذ الأعمال والنقل والتخلص من النواتج طبقا للمواصفات العامة لإنشاء الطرق الحضرية.",
