                          "id":  "roads-item-5-003",
                          "code":  "5-3",
                          "name":  "تنفيذ اعمال حفريات عادية في كافة أنواع التربة غير الصخرية مثل الطين والطمي...",
                          "description":  "تنفيذ اعمال حفريات عادية في كافة أنواع التربة غير الصخرية مثل الطين والطمي والرمل والمواد الركامية أو الصخور المفككة أو الطرية باستخدام طرق ومعدات الحفر العادية مثل البلدوزر وآليات الحفر المشابهة دون الحاجة إلى التفتيت المسبق أو التفجير شامل تسوية السطح طبقاً للمنسوب المطلوب و تنفيذ وإنهاء كافة الأعمال بما في ذلك أعمال الدراسات والتدعيم و سند جوانب الحفر وحماية المنشآت القائمة وحماية المرافق القائمة وتوفير وتشغيل الاليات والمعدات والعمالة وإجراء الاختبارات والقياسات وكل ما يلزم لتنفيذ الأعمال والتخلص من ناتج الحفر طبقًا للمخططات والمواصفات الخاصة وطبقا للمواصفات العامة لإنشاء الطرق الحضرية.",
