                          "description":  "تنفيذ اعمال حفريات في الصخور القاسية والمتماسكة مثل الصخور الجيرية القاسية أو الصفيحية أو البازلتية باستخدام طرق الحفر الصخري المختلفة بالتفتيت و/أو التفجير شامل تنفيذ وإنهاء كافة الأعمال بما في ذلك أعمال الدراسات والتدعيم و سند جوانب الحفر وحماية المنشآت القائمة، وتوفير وتشغيل الاليات والمعدات والعمالة وإجراء الاختبارات والقياسات وكل ما يلزم لتنفيذ الأعمال والتخلص من ناتج الحفر طبقًا للمخططات والمواصفات الخاصة وطبقا للمواصفات العامة لإنشاء الطرق الحضرية.",
