                          "description":  "توريد تنفيذ أعمال الردم من التربة الحصوية المتدرجة الناتجة عن الحفر والمطابقة للمواصفات على ان يتم فردها على طبقات ورشها بالمياه للوصول الى نسبة الرطوبة المطلوبة والدمك الجيد بالهراسات للوصول إلى نسبة الكثافة الجافة المطلوبة طبقاً للمواصفات ويتم التنفيذ طبقاً للمناسيب التصميمية ووثائق العقد وشامل كافة المعدات والعمالة وإجراء الاختبارات والقياسات وكل ما يلزم لتنفيذ الأعمال طبقا للمواصفات الخاصة والمواصفات العامة لإنشاء الطرق الحضرية.",
