        "name":  "صيانة  بطبقة (Microsurfacing)",
        "description":  "صيانة  بطبقة (Microsurfacing):\nصيانة للرصف الأسفلتي بطبقة (Microsurfacing)، وذلك بتوريد وتطبيق طبقة سطحية رقيقة بسماكة  تتراوح من 10 الى 15 مم مكونة من مستحلب أسفلتي بوليمري معدل (Polymer Modified Emulsion) وركام عالي الجودة متدرج ومواد مالئة معدنية ومضافات محسنة وماء، \nيشمل البند تنظيف السطح جيداً وإزالة الأتربة والمواد المفككة والزيوت وأي ملوثات قد تؤثر على الالتصاق، ومعالجة العيوب السطحية البسيطة والشقوق المحدودة قبل التنفيذ عند الحاجة، ثم تنفيذ طبقة الميكروسرفيسنج بالتدرج المناسب (Type II أو Type III) حسب حالة الطريق وحجم الحركة المرورية.\nيجب أن تحقق الخلطة مقاومة مناسبة للتخدد والانزلاق والتآكل مع توفير سطح متجانس  يمنع نفاذ المياه إلى طبقات الرصف.\nيشمل البند جميع أعمال التوريد والخلط والفرد والتشطيب والتحكم المروري المؤقت والاختبارات وضبط الجودة وفتح الطريق للحركة المرورية بعد اكتمال زمن التصلب اللازم،  وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
