        "description":  "صيانة بخلطة الرمل الساخن (Sand Asphalt):\nمعالجة وقائية سطحية بفرد خليط من الأسفلت الرملي الساخن على سطح الرصف لتجديد السطح ومعالجة العيوب السطحية والتأكسد، بسماكة تتراوح بين (20 - 40 ملم)، يشمل البند تنظيف وتجهيز السطح القائم ورش طلاء لاصق مناسب، وتوريد وفرش ودمك الخلطة الرملية الساخنة حتى تحقيق الكثافة المطلوبة وتسوية السطح. وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
