        "description":  "مطبات صناعية مشطية (Comb-Type Humps):\n توريد وتركيب مطبات صناعية مشطية (Comb-Type Humps) مصنوعة من المطاط المقوى أو المواد المركبة عالية التحمل المعتمدة، بعرض كامل المسار أو الطريق وبالأبعاد المعتمدة من الجهة المالكة للطريق، وبارتفاع يتراوح بين (50 - 75 مم) وعرض إجمالي يتراوح بين (300 - 500 مم) للمجموعة الواحدة أو حسب المخططات المعتمدة. يشمل البند توريد وتركيب جميع القطع والوحدات المكونة للمطب، والمسامير والمثبتات الميكانيكية المقاومة للصدأ، والشرائح والعواكس عالية الانعكاسية، وأعمال التحديد والضبط والتثبيت على سطح الرصف، وتنفيذ الدهانات والعلامات والتحذيرات المرورية اللازمة عند الحاجة، مع المحافظة على استواء سطح الطريق وسلامة الرصف القائم، وذلك وفق كود الطرق السعودي وأدلة الوزارة والمواصفات الفنية المعتمدة وتعليمات المهندس المشرف.",
