        "description":  "مطبات صناعية متنقلة (Portable Speed Humps):\n توريد وتركيب مطبات صناعية متنقلة (Portable Speed Humps) مصنوعة من المطاط الصناعي المقوى أو المواد المركبة عالية التحمل المعتمدة، قابلة للفك والتركيب والنقل وإعادة الاستخدام، بالأبعاد المعتمدة وبعرض يغطي كامل المسار أو الجزء المحدد بالمخططات، وبارتفاع يتراوح بين (50 - 75 مم) أو حسب المتطلبات يشمل البند توريد جميع الوحدات والعناصر المكونة للمطب، ووسائل التثبيت الميكانيكية أو المؤقتة، والعواكس والشرائح التحذيرية عالية الانعكاسية، والأغطية الطرفية (End Caps)، وأعمال التركيب والمحاذاة والتثبيت وضمان ثبات المطب أثناء التشغيل، مع إمكانية فكه وإعادة تركيبه دون إلحاق ضرر بسطح الرصف. كما يشمل البند جميع المواد والمعدات والعمالة اللازمة  وذلك وفق كود الطرق السعودي وأدلة الوزارة  وتعليمات المهندس المشرف.",
