        "description":  "استبدال وتركيب عواكس أوتاد الطرق المضيئة بالطاقة الشمسية (Solar Road Studs)\nتوريد وتركيب عواكس أوتاد طرق معدنية مضيئة بالطاقة الشمسية مقاس (15 × 15 سم) ذات وجه عاكس واحد، مصنعة من هيكل معدني عالي المقاومة للأحمال والصدمات والعوامل الجوية، ومزودة بخلايا شمسية مدمجة ووحدة إضاءة LED عالية السطوع وبطارية قابلة لإعادة الشحن، مع نظام تشغيل أوتوماتيكي للإضاءة، بالألوان المعتمدة وفق اتجاه الحركة المرورية، شاملا إزالة العواكس التالفة إن وجدت، وتجهيز وتنظيف سطح التثبيت، وتوريد وتركيب جميع ملحقات التثبيت والمواد اللاصقة أو المرابط المعتمدة، وإجراء الاختبارات اللازمة للتشغيل والتأكد من كفاءة الشحن والإضاءة وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
