        "description":  "استبدال وتركيب إشارة مرورية رقمية للمشاة (Pedestrian Signal)\nتوريد واستبدال وتركيب إشارة مرورية رقمية للمشاة من نوع LED عالية الوضوح، مزودة بعداد زمني تنازلي (Countdown Timer) وإشارات العبور والتوقف للمشاة، ومطابقة للمواصفات المعتمدة لأنظمة الإشارات المرورية الحضرية، شاملا جميع الأعمال المدنية والكهربائية اللازمة من القواعد الخرسانية وقواعد التثبيت والأعمدة والأذرع إن وجدت، وتمديدات الكابلات والمواسير وغرف التفتيش والربط مع وحدة التحكم المروري القائمة أو الجديدة، وجميع أعمال البرمجة والتشغيل والاختبارات والتنسيق مع الجهات المختصة، وإزالة وترحيل العناصر التالفة، وتسليم النظام جاهزا للتشغيل بكامل ملحقاته، وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
