        "name":  "تأهيل طبقة القاعدة الترابية",
        "description":  "تأهيل طبقة القاعدة الترابية:\nتأهيل طبقة القاعدة الترابية من خلال إزالة الطبقات غير الصالحة أو المتضررة وإعادة إنشائها بسماكة (20 سم) أو حسب ما يحدده المهندس المشرف، ويشمل ذلك أعمال الحفر والتحميل والنقل والتخلص من المواد المستبعدة، وتوريد مواد إحلال معتمدة وفرشها وتسويتها وترطيبها ودمكها حتى تحقيق الكثافة المطلوبة.\nيجب ألا يقل تصنيف المواد عن (A-2-4) وفق تصنيف AASHTO، وألا يقل التصنيف عن (A-1-b) في المواقع التي تعلوها طبقات أسفلتية أو في المناطق ذات منسوب المياه الجوفية المرتفع أو المعرضة للرطوبة كما يجب أن تكون المواد خالية من المواد العضوية والشوائب والعناصر الضارة، وأن تحقق متطلبات التدرج وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
