        "name":  "إعادة تأهيل طبقة ما تحت الأساس الركامية Subbase",
        "description":  "إعادة تأهيل طبقة ما تحت الأساس الركامية Subbase:\nإعادة تأهيل طبقة ما تحت الأساس الركامية بسماكة مدموكة (20 سم)، وتشمل إزالة الطبقة القائمة غير الصالحة أو المتضررة والتخلص منها، ثم توريد وفرش مادة ركامية متدرجة (Aggregate Subbase) مطابقة لمتطلبات طبقات ما تحت الأساس وان تكون على طبقات لا تزيد سماكة الطبقة الواحدة عن الحد المسموح، مع التسوية والترطيب بنسبة الرطوبة المثلى (±2%) والدمك حتى الحصول على كثافة لا تقل عن (95%) من الكثافة الجافة العظمى حسب اختبار بروكتور المعدل، مع مراعاة المناسيب والميول اللازمة لتصريف مياه الأمطار. يشمل البند جميع المواد والمعدات والعمالة والاختبارات اللازمة لاعتماد الأعمال وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
