        "description":  "إعادة تأهيل وفرد طبقة أساس حجري Aggregate Base Course:\nإعادة تأهيل طبقة الأساس الحجري بسماكة مدموكة (20 سم)، وتشمل إزالة الطبقة القائمة والتخلص منها، ثم توريد وفرش ركام أساس حجري مطابق للتدرج والخصائص الفيزيائية المحددة بالمواصفات صنف (......) تدرج (.........) يفرش الركام ويسوى ويرش بالماء عند نسبة الرطوبة المثلى (±2%) ثم يدمك بالرصاصات حتى الحصول على كثافة لا تقل عن (100%) من الكثافة الجافة العظمى حسب بروكتور المعدل، على أن تحقق المادة نسبة تحمل كاليفورنيا (CBR) المطلوبة بالمواصفة حسب صنف طبقة الاساس، مع المحافظة على المناسيب والميول التصميمية. يشمل البند جميع المواد والمعدات والعمالة والاختبارات اللازمة لاعتماد الأعمال وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
