        "itemNo":  "5-10",
        "name":  "الكشط وإعادة السفلتة Mill \u0026 Repave",
        "description":  "الكشط وإعادة السفلتة Mill \u0026 Repave:\nصيانة وإعادة تأهيل الرصف الأسفلتي بطريقة الكشط وإعادة السفلتة (Mill \u0026 Repave)، وذلك بكشط الطبقة الأسفلتية القائمة بسماكة لا تقل عن (4 سم) باستخدام ماكينة كشط الأسفلت مع نقل نواتج الكشط والتخلص منها حسب تعليمات الجهات المشرفة يشمل البند تنظيف السطح المكشوط ومعالجة أي عيوب أو مناطق ضعيفة أو متضررة تظهر بعد الكشط كما يشمل رش مادة رابطة من الإسفلت السائل RC-2 بمعدل (0.20 لتر/م2)، ثم توريد وفرش ودمك طبقة أسفلتية سطحية (Wearing Course) من خلطة أسفلتية ساخنة بطريقة مارشال صنف (......) تدرج (......) وبالسماكة المطلوبة حسب المخططات وجداول الكميات.تكون الخلطة الأسفلتية مدعمة بألياف تسليح اصطناعية مخلوطة (Synthetic Fiber Blend) ذات مقاومة عالية للشد، مكونة من مزيج من ألياف البارا أراميد (Para-Aramid Fiber) وألياف البولي أوليفين (Polyolefin Fiber)، وبمعدل إضافة لا يقل عن (0.50 كجم/طن) من الخلطة الأسفلتية، وذلك وفق متطلبات المواصفة ASTM D8395-23 وذلك وفق كود الطرق السعودي وادلة الوزارة وتعليمات المهندس المشرف.",
